1	import { NextResponse } from "next/server";
2	import { getSessionUser } from "@/lib/auth-helpers";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	import { briefRequestSchema } from "@/lib/ai/brief-schema";
5	import { generateCampaignBrief, MissingOpenAIKeyError } from "@/lib/ai/generate-brief";
6	import { logger } from "@/lib/logger";
7	
8	// Node runtime — the AI SDK + provider are not Edge-safe here.
9	export const runtime = "nodejs";
10	
11	const AI_RATE_LIMIT = 10; // requests
12	const AI_RATE_WINDOW_MS = 60_000; // per minute per user
13	
14	export async function POST(request: Request) {
15	  // 1. Authn/authz: only brands/agencies can generate briefs (default-deny).
16	  const user = await getSessionUser();
17	  if (!user) {
18	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
19	  }
20	  if (!["COMPANY", "AGENCY", "ADMIN"].includes(user.role)) {
21	    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
22	  }
23	
24	  // 2. Rate limit the expensive endpoint (OWASP-RATELIMIT-001).
25	  const limit = checkRateLimit(`ai-brief:${user.id}`, AI_RATE_LIMIT, AI_RATE_WINDOW_MS);
26	  if (!limit.allowed) {
27	    return NextResponse.json(
28	      { error: "Too many requests. Please slow down." },
29	      { status: 429, headers: { "Retry-After": String(limit.retryAfterSeconds) } },
30	    );
31	  }
32	
33	  // 3. Validate input (BP-INPUTVAL-001, strips unknown fields).
34	  let body: unknown;
35	  try {
36	    body = await request.json();
37	  } catch {
38	    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
39	  }
40	  const parsed = briefRequestSchema.safeParse(body);
41	  if (!parsed.success) {
42	    return NextResponse.json(
43	      { error: "Validation failed", issues: parsed.error.flatten().fieldErrors },
44	      { status: 400 },
45	    );
46	  }
47	
48	  // 4. Generate.
49	  try {
50	    const brief = await generateCampaignBrief(parsed.data);
51	    return NextResponse.json({ brief });
52	  } catch (error) {
53	    if (error instanceof MissingOpenAIKeyError) {
54	      return NextResponse.json({ error: error.message }, { status: 503 });
55	    }
56	    logger.error("api.ai.brief.error", {
57	      userId: user.id,
58	      reason: error instanceof Error ? error.message : "unknown",
59	    });
60	    return NextResponse.json({ error: "Failed to generate brief." }, { status: 502 });
61	  }
62	}
