1	import { NextResponse } from "next/server";
2	import { prisma } from "@/lib/prisma";
3	import { logger } from "@/lib/logger";
4	
5	export const runtime = "nodejs";
6	
7	const SLUG_PATTERN = /^[a-zA-Z0-9_-]{6,64}$/;
8	const ALLOWED_SCHEMES = new Set(["http:", "https:"]);
9	
10	function todayUtc(): Date {
11	  const now = new Date();
12	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
13	}
14	
15	/**
16	 * Attribution redirect. Records a click against the booking's post, then
17	 * forwards to the destination. The destination is stored by us at booking
18	 * time (not user-supplied here), and its scheme is re-validated before we
19	 * redirect (SSRF/open-redirect defense in depth — OWASP-SSRF-001).
20	 */
21	export async function GET(
22	  _request: Request,
23	  { params }: { params: Promise<{ slug: string }> },
24	) {
25	  const { slug } = await params;
26	  if (!SLUG_PATTERN.test(slug)) {
27	    return NextResponse.json({ error: "Not found" }, { status: 404 });
28	  }
29	
30	  const booking = await prisma.booking.findUnique({
31	    where: { trackedSlug: slug },
32	    select: { id: true, targetUrl: true },
33	  });
34	  if (!booking) {
35	    return NextResponse.json({ error: "Not found" }, { status: 404 });
36	  }
37	
38	  let destination: URL;
39	  try {
40	    destination = new URL(booking.targetUrl);
41	  } catch {
42	    return NextResponse.json({ error: "Invalid destination" }, { status: 400 });
43	  }
44	  if (!ALLOWED_SCHEMES.has(destination.protocol)) {
45	    return NextResponse.json({ error: "Invalid destination" }, { status: 400 });
46	  }
47	
48	  // Record the click against today's metric row (idempotent per day+booking).
49	  try {
50	    const date = todayUtc();
51	    await prisma.postMetricDaily.upsert({
52	      where: { bookingId_date: { bookingId: booking.id, date } },
53	      create: { bookingId: booking.id, date, clicks: 1 },
54	      update: { clicks: { increment: 1 } },
55	    });
56	  } catch (error) {
57	    // Never block the redirect on a metrics write failure — log and continue.
58	    logger.error("attribution.click.write_failed", {
59	      bookingId: booking.id,
60	      reason: error instanceof Error ? error.message : "unknown",
61	    });
62	  }
63	
64	  return NextResponse.redirect(destination.toString(), { status: 302 });
65	}
