3	function toneFor(score: number): { ring: string; text: string } {
4	  if (score >= 85) return { ring: "text-accent", text: "text-accent-600" };
5	  if (score >= 70) return { ring: "text-brand", text: "text-brand-700" };
6	  return { ring: "text-warning", text: "text-warning" };
7	}
8	
9	/** Circular audience-fit gauge (0..100), Naano's headline match metric. */
10	export function FitScoreRing({
11	  score,
12	  size = 56,
13	  label = "fit",
14	}: {
15	  score: number;
16	  size?: number;
17	  label?: string;
18	}) {
19	  const clamped = Math.max(0, Math.min(100, Math.round(score)));
20	  const tone = toneFor(clamped);
21	  const stroke = 5;
22	  const radius = (size - stroke) / 2;
23	  const circumference = 2 * Math.PI * radius;
24	  const offset = circumference - (clamped / 100) * circumference;
25	
26	  return (
27	    <span
28	      className="relative inline-flex items-center justify-center"
29	      style={{ width: size, height: size }}
30	      title={`${clamped}% audience ${label}`}
31	    >
32	      <svg width={size} height={size} className="-rotate-90">
33	        <circle
34	          cx={size / 2}
35	          cy={size / 2}
36	          r={radius}
37	          fill="none"
38	          stroke="currentColor"
39	          strokeWidth={stroke}
40	          className="text-border"
41	        />
42	        <circle
43	          cx={size / 2}
44	          cy={size / 2}
45	          r={radius}
46	          fill="none"
47	          stroke="currentColor"
48	          strokeWidth={stroke}
49	          strokeLinecap="round"
50	          strokeDasharray={circumference}
51	          strokeDashoffset={offset}
52	          className={cn("transition-all", tone.ring)}
53	        />
54	      </svg>
55	      <span className={cn("absolute text-xs font-bold", tone.text)}>{clamped}</span>
56	    </span>
57	  );
58	}
