7	
8	/** Thrown when the OpenAI key is not configured — surfaced as a clear 503. */
9	export class MissingOpenAIKeyError extends Error {
10	  constructor() {
11	    super("OPENAI_API_KEY is not configured. Add it to .env to enable AI briefs.");
12	    this.name = "MissingOpenAIKeyError";
13	  }
14	}
