16	const SYSTEM_PROMPT = [
17	  "You are a senior B2B LinkedIn campaign strategist for Naano, a creator marketplace.",
18	  "You write briefs that vetted creators turn into authentic, high-performing sponsored posts.",
19	  "Briefs must respect the creator's own voice: give direction, not a script.",
20	  "The brand owns factual accuracy; the creator owns the expression.",
21	  "Be specific, concrete, and free of generic marketing fluff.",
22	].join(" ");
23	
24	function buildPrompt(input: BriefRequest): string {
25	  const lines = [
26	    `Product / company: ${input.productName}`,
27	    `What it does: ${input.productDescription}`,
28	    `Target audience (ICP): ${input.targetAudience}`,
29	    `Campaign objective: ${input.objective}`,
30	  ];
31	  if (input.vertical) lines.push(`Vertical: ${input.vertical}`);
32	  if (input.keyPoints) lines.push(`Extra notes to consider: ${input.keyPoints}`);
33	  lines.push(
34	    "Produce a single-post campaign brief a B2B LinkedIn creator can act on immediately.",
35	  );
36	  return lines.join("\n");
37	}
