39	/**
40	 * Generate a structured campaign brief via OpenAI. Validates the key at the
41	 * boundary and enforces a hard timeout (BP-RESOURCE-001). Never logs the key.
42	 */
43	export async function generateCampaignBrief(input: BriefRequest): Promise<GeneratedBrief> {
44	  if (!env.OPENAI_API_KEY) throw new MissingOpenAIKeyError();
45	
46	  const openai = createOpenAI({ apiKey: env.OPENAI_API_KEY });
47	
48	  try {
49	    const { object } = await generateObject({
50	      model: openai(env.OPENAI_BRIEF_MODEL),
51	      schema: briefSchema,
52	      system: SYSTEM_PROMPT,
53	      prompt: buildPrompt(input),
54	      abortSignal: AbortSignal.timeout(AI_BRIEF_TIMEOUT_MS),
55	    });
56	    logger.info("ai.brief.generated", {
57	      model: env.OPENAI_BRIEF_MODEL,
58	      product: input.productName,
59	    });
60	    return object;
61	  } catch (error) {
62	    // Wrap with context but never leak credentials (BP-ERR-001).
63	    logger.error("ai.brief.failed", {
64	      model: env.OPENAI_BRIEF_MODEL,
65	      reason: error instanceof Error ? error.message : "unknown",
66	    });
67	    throw new Error("Failed to generate campaign brief from the AI provider.");
68	  }
69	}
