309	/**
310	 * Split a single CSV line into fields, honoring double-quoted fields that may
311	 * contain commas. Intentionally minimal — enough for pasted spreadsheet rows.
312	 */
313	function splitCsvLine(line: string): string[] {
314	  const fields: string[] = [];
315	  let current = "";
316	  let insideQuotes = false;
317	  for (let i = 0; i < line.length; i += 1) {
318	    const char = line[i];
319	    if (char === '"') {
320	      if (insideQuotes && line[i + 1] === '"') {
321	        current += '"';
322	        i += 1;
323	      } else {
324	        insideQuotes = !insideQuotes;
325	      }
326	    } else if (char === "," && !insideQuotes) {
327	      fields.push(current);
328	      current = "";
329	    } else {
330	      current += char;
331	    }
332	  }
333	  fields.push(current);
334	  return fields.map((field) => field.trim());
335	}
336	
337	/** Map header labels to their column index. Missing headers -> -1. */
338	function buildColumnIndex(headerFields: string[]) {
339	  const normalized = headerFields.map((field) => field.toLowerCase());
340	  return {
341	    name: normalized.findIndex((field) => field === "name" || field === "displayname"),
342	    headline: normalized.indexOf("headline"),
343	    followers: normalized.indexOf("followers"),
344	    pricePerPost: normalized.findIndex(
345	      (field) => field === "priceperpost" || field === "price",
346	    ),
347	    verticals: normalized.indexOf("verticals"),
348	  };
349	}
350	
351	/** Parse a non-negative integer from a raw cell; NaN on invalid input. */
352	function parseIntegerCell(raw: string | undefined): number {
353	  if (raw === undefined) return Number.NaN;
354	  const cleaned = raw.replace(/[,\s€]/g, "");
355	  if (cleaned === "") return Number.NaN;
356	  const value = Number(cleaned);
357	  if (!Number.isFinite(value)) return Number.NaN;
358	  return Math.trunc(value);
359	}
360	
361	type ColumnIndex = ReturnType<typeof buildColumnIndex>;
362	
363	/** Validate one already-split data row into a typed roster entry, or null. */
364	function parseCsvDataRow(fields: string[], columns: ColumnIndex): ParsedCsvRow | null {
365	  const displayName = columns.name >= 0 ? (fields[columns.name] ?? "").trim() : "";
366	  const headline = columns.headline >= 0 ? (fields[columns.headline] ?? "").trim() : "";
367	  const followers = parseIntegerCell(fields[columns.followers]);
368	  const pricePerPost = parseIntegerCell(fields[columns.pricePerPost]);
369	  const rawVerticals = columns.verticals >= 0 ? (fields[columns.verticals] ?? "") : "";
370	  const verticals = sanitizeVerticals(
371	    rawVerticals
372	      .split(VERTICAL_SEPARATOR_PATTERN)
373	      .map((entry) => entry.trim())
374	      .filter(Boolean),
375	  );
376	
377	  const candidate = { displayName, headline, followers, pricePerPost, verticals };
378	  const parsed = managedCreatorSchema.safeParse(candidate);
379	  if (!parsed.success) return null;
380	  return {
381	    displayName: parsed.data.displayName,
382	    headline: parsed.data.headline,
383	    followers: parsed.data.followers,
384	    pricePerPost: parsed.data.pricePerPost,
385	    verticals: parsed.data.verticals,
386	  };
387	}
388	
389	/** Parse pasted CSV into validated rows plus a skipped count (robust to junk). */
390	function parseRosterCsv(csv: string): { rows: ParsedCsvRow[]; skipped: number } {
391	  const lines = csv
392	    .split(/\r?\n/)
393	    .map((line) => line.trim())
394	    .filter((line) => line.length > 0);
395	
396	  if (lines.length === 0) return { rows: [], skipped: 0 };
397	
398	  const columns = buildColumnIndex(splitCsvLine(lines[0]));
399	  const dataLines = lines.slice(1, 1 + CSV_MAX_ROWS);
400	
401	  const rows: ParsedCsvRow[] = [];
402	  let skipped = 0;
403	  for (const line of dataLines) {
404	    const parsedRow = parseCsvDataRow(splitCsvLine(line), columns);
405	    if (parsedRow) {
406	      rows.push(parsedRow);
407	    } else {
408	      skipped += 1;
409	    }
410	  }
411	  return { rows, skipped };
412	}
413	
414	/** Bulk-create managed creators from pasted CSV; returns a created/skipped summary. */
415	export async function importRosterCsv(csv: string): Promise<ImportResult> {
416	  const { agency } = await requireAgency();
417	  if (agency.type !== "CREATOR_AGENCY") {
418	    return { ok: false, error: "A roster is only available to creator agencies" };
419	  }
420	
421	  const parsed = csvImportSchema.safeParse({ csv });
422	  if (!parsed.success) {
423	    return { ok: false, error: firstZodError(parsed.error) };
424	  }
425	
426	  const { rows, skipped } = parseRosterCsv(parsed.data.csv);
427	  if (rows.length === 0) {
428	    return {
429	      ok: false,
430	      error:
431	        "No valid rows found. Expected headers: name, headline, followers, pricePerPost, verticals",
432	    };
433	  }
434	
435	  const defaults = buildManagedCreatorDefaults();
436	  await prisma.creatorProfile.createMany({
437	    data: rows.map((row) => ({
438	      ...defaults,
439	      managedByAgencyId: agency.id,
440	      displayName: row.displayName,
441	      headline: row.headline,
442	      followers: row.followers,
443	      pricePerPost: row.pricePerPost,
444	      verticals: row.verticals,
445	    })),
446	  });
447	
448	  revalidatePath(AGENCY_ROSTER_PATH);
449	  revalidatePath(AGENCY_PORTFOLIO_PATH);
450	  return {
451	    ok: true,
452	    created: rows.length,
453	    skipped,
454	    message: `Imported ${rows.length} creator${rows.length === 1 ? "" : "s"}${
455	      skipped > 0 ? `, skipped ${skipped} invalid row${skipped === 1 ? "" : "s"}` : ""
456	    }`,
457	  };
458	}
459

