// Read-side helpers for the company (brand) dashboard.
//
// All exported functions require the caller to pass an already-authorized
// `companyId` (sourced from requireCompany() in the page/action). They ONLY
// ever query records scoped to that company id (OWASP-IDOR-001) — nothing here
// trusts a client-supplied id for ownership.
//
// These are pure data-shaping helpers over Prisma reads: they never mutate.

import { prisma } from "@/lib/prisma";
import { computeFitScore, asAudienceMap, type IcpTarget } from "@/lib/fit-score";
import { BOOKING_PIPELINE } from "@/lib/constants";
import type { CreatorProfile } from "@prisma/client";

// --- Tunable constants (BP-CONST-001 — no magic numbers in logic) -----------

/** Days of history rendered in the overview / attribution time-series charts. */
export const METRICS_WINDOW_DAYS = 21;

/**
 * Assumed value of a single captured lead, used purely to render an indicative
 * "attributed pipeline" figure. This is a display proxy, clearly labelled in the
 * UI as an estimate — not a stored monetary amount.
 */
export const ASSUMED_DEAL_VALUE_EUROS = 2500;

/** Booking statuses that count as a "live post" for KPI purposes. */
export const LIVE_BOOKING_STATUSES = ["LIVE", "COMPLETED", "PAID"] as const;

/** How many top-matched creators to preview on the overview page. */
export const TOP_CREATORS_PREVIEW_LIMIT = 5;

/** How many recent campaigns to preview on the overview page. */
export const RECENT_CAMPAIGNS_PREVIEW_LIMIT = 5;

// --- Shared date helpers ----------------------------------------------------

/** Midnight UTC for `date` — matches how PostMetricDaily rows are keyed. */
export function toUtcDay(date: Date): Date {
  return new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
}

/** The inclusive-start UTC day `days` before today (for windowed queries). */
export function windowStartDay(days: number): Date {
  const start = toUtcDay(new Date());
  start.setUTCDate(start.getUTCDate() - (days - 1));
  return start;
}

/** "YYYY-MM-DD" key for a date, used to bucket a time series map. */
function dayKey(date: Date): string {
  return toUtcDay(date).toISOString().slice(0, 10);
}

// --- Types ------------------------------------------------------------------

export type MetricPoint = {
  date: string; // YYYY-MM-DD
  impressions: number;
  clicks: number;
  leads: number;
};

export type CompanyKpis = {
  activeCampaigns: number;
  livePosts: number;
  totalClicks: number;
  totalLeads: number;
  totalImpressions: number;
  estimatedPipelineEuros: number;
};

export type RankedCreator = {
  creator: CreatorProfile;
  fitScore: number;
};

export type CampaignPerformanceRow = {
  campaignId: string;
  name: string;
  status: string;
  budget: number;
  postCount: number;
  impressions: number;
  clicks: number;
  leads: number;
  spend: number;
};

// --- ICP + fit ranking ------------------------------------------------------

/** Build the fit-score ICP target from a company profile's stored preferences. */
export function icpTargetForCompany(company: {
  icpFunctions: string[];
  icpSeniorities: string[];
  vertical: string | null;
}): IcpTarget {
  return {
    functions: company.icpFunctions,
    seniorities: company.icpSeniorities,
    vertical: company.vertical,
  };
}

/** Score a single creator against a company ICP (deterministic, 0..100). */
export function scoreCreator(target: IcpTarget, creator: CreatorProfile): number {
  return computeFitScore(target, {
    audienceByFunction: asAudienceMap(creator.audienceByFunction),
    audienceBySeniority: asAudienceMap(creator.audienceBySeniority),
    verticals: creator.verticals,
  });
}

/** Attach fit scores to creators and sort highest-first. Does not mutate input. */
export function rankCreatorsByFit(
  target: IcpTarget,
  creators: CreatorProfile[],
): RankedCreator[] {
  return creators
    .map((creator) => ({ creator, fitScore: scoreCreator(target, creator) }))
    .sort((a, b) => b.fitScore - a.fitScore);
}

// --- Metric aggregation -----------------------------------------------------

type RawMetricRow = { date: Date; impressions: number; clicks: number; leads: number };

/**
 * Collapse per-booking daily metric rows into a single dense time series over a
 * fixed trailing window. Days with no data are emitted as zeroes so charts show
 * a continuous axis.
 */
export function buildMetricSeries(
  rows: RawMetricRow[],
  windowDays: number = METRICS_WINDOW_DAYS,
): MetricPoint[] {
  const byDay = new Map<string, MetricPoint>();
  const start = windowStartDay(windowDays);

  for (let offset = 0; offset < windowDays; offset += 1) {
    const day = new Date(start);
    day.setUTCDate(day.getUTCDate() + offset);
    const key = dayKey(day);
    byDay.set(key, { date: key, impressions: 0, clicks: 0, leads: 0 });
  }

  for (const row of rows) {
    const key = dayKey(row.date);
    const point = byDay.get(key);
    if (!point) continue; // outside the window — ignore
    point.impressions += row.impressions;
    point.clicks += row.clicks;
    point.leads += row.leads;
  }

  return Array.from(byDay.values());
}

/** Sum a metric series into window totals. */
export function sumMetrics(points: MetricPoint[]): {
  impressions: number;
  clicks: number;
  leads: number;
} {
  return points.reduce(
    (acc, point) => ({
      impressions: acc.impressions + point.impressions,
      clicks: acc.clicks + point.clicks,
      leads: acc.leads + point.leads,
    }),
    { impressions: 0, clicks: 0, leads: 0 },
  );
}

// --- Company-scoped aggregate reads -----------------------------------------

/**
 * The trailing-window metric series aggregated across every booking of every
 * campaign owned by `companyId`. Returns dense zero-filled points.
 */
export async function companyMetricSeries(
  companyId: string,
  windowDays: number = METRICS_WINDOW_DAYS,
): Promise<MetricPoint[]> {
  const rows = await prisma.postMetricDaily.findMany({
    where: {
      date: { gte: windowStartDay(windowDays) },
      booking: { campaign: { companyProfileId: companyId } },
    },
    select: { date: true, impressions: true, clicks: true, leads: true },
  });
  return buildMetricSeries(rows, windowDays);
}

/**
 * The trailing-window metric series for a single campaign. The caller MUST have
 * already verified the campaign belongs to the current company; we still scope
 * the query defensively through the campaign's company id.
 */
export async function campaignMetricSeries(
  companyId: string,
  campaignId: string,
  windowDays: number = METRICS_WINDOW_DAYS,
): Promise<MetricPoint[]> {
  const rows = await prisma.postMetricDaily.findMany({
    where: {
      date: { gte: windowStartDay(windowDays) },
      booking: { campaignId, campaign: { companyProfileId: companyId } },
    },
    select: { date: true, impressions: true, clicks: true, leads: true },
  });
  return buildMetricSeries(rows, windowDays);
}

/** Headline KPIs for the overview page — all scoped to `companyId`. */
export async function companyKpis(companyId: string): Promise<CompanyKpis> {
  const [activeCampaigns, livePosts, metricTotals, totalLeads] = await Promise.all([
    prisma.campaign.count({
      where: { companyProfileId: companyId, status: "ACTIVE" },
    }),
    prisma.booking.count({
      where: {
        campaign: { companyProfileId: companyId },
        status: { in: [...LIVE_BOOKING_STATUSES] },
      },
    }),
    prisma.postMetricDaily.aggregate({
      where: { booking: { campaign: { companyProfileId: companyId } } },
      _sum: { clicks: true, leads: true, impressions: true },
    }),
    prisma.lead.count({
      where: { booking: { campaign: { companyProfileId: companyId } } },
    }),
  ]);

  return {
    activeCampaigns,
    livePosts,
    totalClicks: metricTotals._sum.clicks ?? 0,
    totalLeads,
    totalImpressions: metricTotals._sum.impressions ?? 0,
    estimatedPipelineEuros: totalLeads * ASSUMED_DEAL_VALUE_EUROS,
  };
}

/**
 * Per-campaign performance rollup for the reports page. One row per campaign
 * owned by `companyId`, with lifetime (not windowed) metric sums and booked spend.
 */
export async function campaignPerformanceRows(
  companyId: string,
): Promise<CampaignPerformanceRow[]> {
  const campaigns = await prisma.campaign.findMany({
    where: { companyProfileId: companyId },
    orderBy: { createdAt: "desc" },
    include: {
      bookings: {
        select: {
          pricePerPost: true,
          status: true,
          metrics: { select: { impressions: true, clicks: true, leads: true } },
        },
      },
    },
  });

  return campaigns.map((campaign) => {
    let impressions = 0;
    let clicks = 0;
    let leads = 0;
    let spend = 0;
    for (const booking of campaign.bookings) {
      if (isSpendCounted(booking.status)) spend += booking.pricePerPost;
      for (const metric of booking.metrics) {
        impressions += metric.impressions;
        clicks += metric.clicks;
        leads += metric.leads;
      }
    }
    return {
      campaignId: campaign.id,
      name: campaign.name,
      status: campaign.status,
      budget: campaign.budget,
      postCount: campaign.bookings.length,
      impressions,
      clicks,
      leads,
      spend,
    };
  });
}

/**
 * A booking's price counts as committed spend once the creator is locked in
 * (APPROVED onward). Earlier stages are still speculative.
 */
function isSpendCounted(status: string): boolean {
  const committedIndex = BOOKING_PIPELINE.indexOf(
    "APPROVED" as (typeof BOOKING_PIPELINE)[number],
  );
  const statusIndex = BOOKING_PIPELINE.indexOf(status as (typeof BOOKING_PIPELINE)[number]);
  return statusIndex >= committedIndex && committedIndex >= 0;
}

"use server";

// Company (brand) campaign mutations.
//
// Every action:
//   - starts with "use server"
//   - resolves the current company from the server session (requireCompany),
//     never from a client-supplied id (OWASP-IDOR-001)
//   - validates input with zod, using explicit DTOs (OWASP-MASS-001 /
//     BP-INPUTVAL-001) — we never spread a request body into a Prisma write
//   - re-fetches the target record scoped to company.id before mutating, and
//     treats "not owned" identically to "not found" (404-style, OWASP-IDOR-001)
//   - enforces the allowed state machine for status changes
//   - revalidates the affected routes

import { revalidatePath } from "next/cache";
import { z } from "zod";
import type { CampaignStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { requireCompany } from "@/lib/auth-helpers";
import { VERTICALS } from "@/lib/constants";
import { briefSchema } from "@/lib/ai/brief-schema";

// --- Result contract (mirrors the codebase's agency/creator actions) --------

export type ActionResult =
  | { ok: true; message?: string; campaignId?: string }
  | { ok: false; error: string };

// --- Domain limits (BP-CONST-001) -------------------------------------------

const CAMPAIGN_NAME_MAX_LEN = 140;
const OBJECTIVE_MAX_LEN = 300;
const ICP_MAX_LEN = 600;
const MIN_BUDGET = 0;
const MAX_BUDGET = 100_000_000; // €100M ceiling — guards typo/overflow abuse
const MIN_TARGET_POSTS = 0;
const MAX_TARGET_POSTS = 1000;
const BRIEF_STRING_MAX_LEN = 600;
const BRIEF_LIST_ITEM_MAX_LEN = 240;
const BRIEF_LIST_MAX_ITEMS = 8;
const BRIEF_PROMPT_MAX_LEN = 4000;

const CAMPAIGNS_LIST_PATH = "/app/campaigns";
const OVERVIEW_PATH = "/app";

const VALID_VERTICALS = new Set<string>(VERTICALS);

/**
 * Allowed campaign status transitions (company-driven lifecycle).
 * DRAFT → ACTIVE → COMPLETED, with ARCHIVED reachable from any non-archived state.
 */
const CAMPAIGN_TRANSITIONS: Record<CampaignStatus, CampaignStatus[]> = {
  DRAFT: ["ACTIVE", "ARCHIVED"],
  ACTIVE: ["COMPLETED", "ARCHIVED"],
  COMPLETED: ["ARCHIVED"],
  ARCHIVED: [],
};

// --- Input schemas (explicit DTOs, strict — unknown fields rejected) --------

const optionalVertical = z
  .string()
  .trim()
  .max(80)
  .optional()
  .refine((value) => value === undefined || value === "" || VALID_VERTICALS.has(value), {
    message: "Unknown vertical",
  });

const briefInputSchema = briefSchema
  .extend({
    angle: z.string().trim().min(1).max(BRIEF_STRING_MAX_LEN),
    hook: z.string().trim().min(1).max(BRIEF_STRING_MAX_LEN),
    cta: z.string().trim().min(1).max(BRIEF_STRING_MAX_LEN),
    audience: z.string().trim().min(1).max(BRIEF_STRING_MAX_LEN),
    toneOfVoice: z.string().trim().min(1).max(BRIEF_STRING_MAX_LEN),
    keyMessages: z
      .array(z.string().trim().min(1).max(BRIEF_LIST_ITEM_MAX_LEN))
      .max(BRIEF_LIST_MAX_ITEMS),
    doList: z
      .array(z.string().trim().min(1).max(BRIEF_LIST_ITEM_MAX_LEN))
      .max(BRIEF_LIST_MAX_ITEMS),
    dontList: z
      .array(z.string().trim().min(1).max(BRIEF_LIST_ITEM_MAX_LEN))
      .max(BRIEF_LIST_MAX_ITEMS),
    proofPoints: z
      .array(z.string().trim().min(1).max(BRIEF_LIST_ITEM_MAX_LEN))
      .max(BRIEF_LIST_MAX_ITEMS),
  })
  .strict();

const createCampaignSchema = z
  .object({
    name: z.string().trim().min(1, "Campaign name is required").max(CAMPAIGN_NAME_MAX_LEN),
    objective: z.string().trim().max(OBJECTIVE_MAX_LEN).optional(),
    vertical: optionalVertical,
    budget: z
      .number()
      .int("Budget must be a whole number of euros")
      .min(MIN_BUDGET, "Budget cannot be negative")
      .max(MAX_BUDGET, "Budget exceeds the allowed maximum"),
    targetPostCount: z
      .number()
      .int("Target posts must be a whole number")
      .min(MIN_TARGET_POSTS, "Target posts cannot be negative")
      .max(MAX_TARGET_POSTS, "Target posts exceeds the allowed maximum"),
    icp: z.string().trim().max(ICP_MAX_LEN).optional(),
    brief: briefInputSchema.optional(),
    briefGeneratedByAI: z.boolean().optional(),
    briefPrompt: z.string().trim().max(BRIEF_PROMPT_MAX_LEN).optional(),
  })
  .strict();

const updateStatusSchema = z
  .object({
    campaignId: z.string().trim().min(1, "Campaign id is required"),
    nextStatus: z.enum(["DRAFT", "ACTIVE", "COMPLETED", "ARCHIVED"]),
  })
  .strict();

export type CreateCampaignInput = z.infer<typeof createCampaignSchema>;

// --- Helpers ----------------------------------------------------------------

function firstZodError(error: z.ZodError): string {
  return error.issues[0]?.message ?? "Invalid input";
}

/** Explicit DTO for the nested Brief create — never spread client input. */
function briefCreateData(
  brief: z.infer<typeof briefInputSchema>,
  generatedByAI: boolean,
  prompt?: string,
) {
  return {
    angle: brief.angle,
    hook: brief.hook,
    cta: brief.cta,
    keyMessages: brief.keyMessages,
    audience: brief.audience,
    toneOfVoice: brief.toneOfVoice,
    doList: brief.doList,
    dontList: brief.dontList,
    proofPoints: brief.proofPoints,
    generatedByAI,
    prompt: prompt && prompt.length > 0 ? prompt : null,
  };
}

// --- Actions ----------------------------------------------------------------

/**
 * Create a campaign (optionally with a brief) owned by the current company.
 * Returns the new campaign id so the caller can redirect to its detail page.
 */
export async function createCampaign(input: CreateCampaignInput): Promise<ActionResult> {
  const { company } = await requireCompany();

  const parsed = createCampaignSchema.safeParse(input);
  if (!parsed.success) {
    return { ok: false, error: firstZodError(parsed.error) };
  }
  const data = parsed.data;

  const campaign = await prisma.campaign.create({
    data: {
      companyProfileId: company.id, // ownership fixed server-side, not from client
      name: data.name,
      status: "DRAFT",
      objective: data.objective && data.objective.length > 0 ? data.objective : null,
      vertical: data.vertical && data.vertical.length > 0 ? data.vertical : null,
      budget: data.budget,
      targetPostCount: data.targetPostCount,
      icp: data.icp && data.icp.length > 0 ? data.icp : null,
      ...(data.brief
        ? {
            brief: {
              create: briefCreateData(
                data.brief,
                data.briefGeneratedByAI ?? false,
                data.briefPrompt,
              ),
            },
          }
        : {}),
    },
    select: { id: true },
  });

  revalidatePath(CAMPAIGNS_LIST_PATH);
  revalidatePath(OVERVIEW_PATH);
  return { ok: true, campaignId: campaign.id, message: "Campaign created" };
}

/**
 * Advance a campaign's status along the allowed lifecycle. Verifies ownership
 * (404-style on miss) and rejects illegal transitions.
 */
export async function updateCampaignStatus(
  campaignId: string,
  nextStatus: CampaignStatus,
): Promise<ActionResult> {
  const { company } = await requireCompany();

  const parsed = updateStatusSchema.safeParse({ campaignId, nextStatus });
  if (!parsed.success) {
    return { ok: false, error: firstZodError(parsed.error) };
  }

  // Ownership check at the data layer (OWASP-IDOR-001).
  const campaign = await prisma.campaign.findFirst({
    where: { id: parsed.data.campaignId, companyProfileId: company.id },
    select: { id: true, status: true },
  });
  if (!campaign) {
    return { ok: false, error: "Campaign not found" };
  }

  const allowed = CAMPAIGN_TRANSITIONS[campaign.status];
  if (!allowed.includes(parsed.data.nextStatus)) {
    return {
      ok: false,
      error: `Cannot move a ${campaign.status.toLowerCase()} campaign to ${parsed.data.nextStatus.toLowerCase()}`,
    };
  }

  await prisma.campaign.update({
    where: { id: campaign.id },
    data: { status: parsed.data.nextStatus },
  });

  revalidatePath(`${CAMPAIGNS_LIST_PATH}/${campaign.id}`);
  revalidatePath(CAMPAIGNS_LIST_PATH);
  revalidatePath(OVERVIEW_PATH);
  return { ok: true, message: `Campaign moved to ${parsed.data.nextStatus.toLowerCase()}` };
}

"use server";

// Company (brand) booking mutations — the creator ↔ campaign relationship.
//
// Booking pipeline (schema BookingStatus): INVITED, ACCEPTED, DECLINED,
// DRAFT_SUBMITTED, APPROVED, SCHEDULED, LIVE, COMPLETED, PAID.
//
// The company DRIVES a specific subset of these transitions. Creator-side
// transitions (accept/decline an invite, submit a draft) are intentionally NOT
// exposed here — the company cannot accept on a creator's behalf. See
// COMPANY_BOOKING_TRANSITIONS below for the exact allowed moves.
//
// Every action re-resolves the company from the session and verifies that the
// booking's campaign is owned by that company before mutating (OWASP-IDOR-001).

import { randomBytes } from "node:crypto";
import { revalidatePath } from "next/cache";
import { z } from "zod";
import type { BookingStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { requireCompany } from "@/lib/auth-helpers";
import { scoreCreator, icpTargetForCompany } from "@/lib/company-queries";

export type ActionResult =
  | { ok: true; message?: string; bookingId?: string }
  | { ok: false; error: string };

// --- Constants (BP-CONST-001) -----------------------------------------------

const TRACKED_SLUG_BYTES = 12; // 96 bits of entropy → ~16 url-safe chars
const PLACEHOLDER_TARGET_URL = "https://naano.com"; // fallback when company has no website

const CAMPAIGNS_LIST_PATH = "/app/campaigns";
const OVERVIEW_PATH = "/app";
const REPORTS_PATH = "/app/reports";

// Bookable campaign states — you can only invite creators onto a live-ish campaign.
const BOOKABLE_CAMPAIGN_STATUSES = new Set<string>(["DRAFT", "ACTIVE"]);

/**
 * Company-driven booking transitions. The KEY is the current status; the VALUE
 * is the set of statuses the COMPANY is permitted to move it to.
 *
 *   DRAFT_SUBMITTED → APPROVED   (approve the creator's submitted draft)
 *   APPROVED        → SCHEDULED  (lock in a publish slot)
 *   SCHEDULED       → LIVE       (mark the post as published)
 *   LIVE            → COMPLETED  (post run finished)
 *   LIVE|COMPLETED  → PAID       (release the creator payout)
 *
 * Everything else (INVITED→ACCEPTED, ACCEPTED→DRAFT_SUBMITTED, *→DECLINED) is a
 * creator-side move and is rejected here by default-deny.
 */
const COMPANY_BOOKING_TRANSITIONS: Partial<Record<BookingStatus, BookingStatus[]>> = {
  DRAFT_SUBMITTED: ["APPROVED"],
  APPROVED: ["SCHEDULED"],
  SCHEDULED: ["LIVE"],
  LIVE: ["COMPLETED", "PAID"],
  COMPLETED: ["PAID"],
};

// --- Input schemas ----------------------------------------------------------

const createBookingSchema = z
  .object({
    campaignId: z.string().trim().min(1, "Campaign is required"),
    creatorId: z.string().trim().min(1, "Creator is required"),
  })
  .strict();

const updateBookingStatusSchema = z
  .object({
    bookingId: z.string().trim().min(1, "Booking id is required"),
    nextStatus: z.enum([
      "INVITED",
      "ACCEPTED",
      "DECLINED",
      "DRAFT_SUBMITTED",
      "APPROVED",
      "SCHEDULED",
      "LIVE",
      "COMPLETED",
      "PAID",
    ]),
  })
  .strict();

// --- Helpers ----------------------------------------------------------------

function firstZodError(error: z.ZodError): string {
  return error.issues[0]?.message ?? "Invalid input";
}

/** Cryptographically-secure, URL-safe slug for the /t/[slug] tracked link. */
function generateTrackedSlug(): string {
  return randomBytes(TRACKED_SLUG_BYTES)
    .toString("base64url")
    .replace(/[^a-zA-Z0-9_-]/g, "")
    .slice(0, 22);
}

/**
 * Build a valid, https attribution destination from the company website (or a
 * safe placeholder), decorated with UTM params. Uses typed URL construction —
 * never string concatenation (OWASP-XSS-001 URL-context guidance).
 */
function buildTargetUrl(companyWebsite: string | null, campaignId: string): string {
  let base: URL;
  try {
    base = new URL(companyWebsite ?? PLACEHOLDER_TARGET_URL);
    if (base.protocol !== "https:" && base.protocol !== "http:") {
      base = new URL(PLACEHOLDER_TARGET_URL);
    }
  } catch {
    base = new URL(PLACEHOLDER_TARGET_URL);
  }
  base.searchParams.set("utm_source", "naano");
  base.searchParams.set("utm_medium", "creator");
  base.searchParams.set("utm_campaign", campaignId);
  return base.toString();
}

// --- Actions ----------------------------------------------------------------

/**
 * Book a creator onto one of the company's campaigns. Validates campaign
 * ownership + bookable state, snapshots the fit score and price, and creates an
 * INVITED booking with a tracked link. Idempotent on the unique
 * (campaignId, creatorId) constraint — a re-book is reported gracefully.
 */
export async function createBooking(
  campaignId: string,
  creatorId: string,
): Promise<ActionResult> {
  const { company } = await requireCompany();

  const parsed = createBookingSchema.safeParse({ campaignId, creatorId });
  if (!parsed.success) {
    return { ok: false, error: firstZodError(parsed.error) };
  }

  // Ownership + state check (OWASP-IDOR-001): the campaign must belong to us.
  const campaign = await prisma.campaign.findFirst({
    where: { id: parsed.data.campaignId, companyProfileId: company.id },
    select: { id: true, status: true },
  });
  if (!campaign) {
    return { ok: false, error: "Campaign not found" };
  }
  if (!BOOKABLE_CAMPAIGN_STATUSES.has(campaign.status)) {
    return {
      ok: false,
      error: "You can only book creators onto draft or active campaigns",
    };
  }

  const creator = await prisma.creatorProfile.findUnique({
    where: { id: parsed.data.creatorId },
    select: {
      id: true,
      pricePerPost: true,
      verticals: true,
      audienceByFunction: true,
      audienceBySeniority: true,
    },
  });
  if (!creator) {
    return { ok: false, error: "Creator not found" };
  }

  // Already booked? The unique (campaignId, creatorId) index is the source of
  // truth; check first for a friendly message, and treat a race as success.
  const existing = await prisma.booking.findUnique({
    where: {
      campaignId_creatorProfileId: {
        campaignId: campaign.id,
        creatorProfileId: creator.id,
      },
    },
    select: { id: true },
  });
  if (existing) {
    return { ok: true, bookingId: existing.id, message: "Creator is already booked on this campaign" };
  }

  const fitScore = scoreCreator(icpTargetForCompany(company), {
    // scoreCreator only reads these fields — pass a minimal shaped object.
    ...creator,
    id: creator.id,
    // The remaining CreatorProfile fields are unused by scoreCreator.
  } as Parameters<typeof scoreCreator>[1]);

  try {
    const booking = await prisma.booking.create({
      data: {
        campaignId: campaign.id,
        creatorProfileId: creator.id,
        status: "INVITED",
        pricePerPost: creator.pricePerPost,
        fitScore,
        trackedSlug: generateTrackedSlug(),
        targetUrl: buildTargetUrl(company.website, campaign.id),
      },
      select: { id: true },
    });

    revalidatePath(`${CAMPAIGNS_LIST_PATH}/${campaign.id}`);
    revalidatePath(CAMPAIGNS_LIST_PATH);
    revalidatePath(OVERVIEW_PATH);
    return { ok: true, bookingId: booking.id, message: "Creator invited to the campaign" };
  } catch {
    // Unique-constraint race (BP-IDEM-001): another request booked concurrently.
    return { ok: true, message: "Creator is already booked on this campaign" };
  }
}

/**
 * Advance a booking along the company-driven pipeline. Verifies the booking's
 * campaign is owned by the current company (404-style on miss) and enforces the
 * allowed transition table. Reaching PAID also settles the creator payout.
 */
export async function updateBookingStatus(
  bookingId: string,
  nextStatus: BookingStatus,
): Promise<ActionResult> {
  const { company } = await requireCompany();

  const parsed = updateBookingStatusSchema.safeParse({ bookingId, nextStatus });
  if (!parsed.success) {
    return { ok: false, error: firstZodError(parsed.error) };
  }

  // Ownership check across the campaign relation (OWASP-IDOR-001).
  const booking = await prisma.booking.findFirst({
    where: {
      id: parsed.data.bookingId,
      campaign: { companyProfileId: company.id },
    },
    select: { id: true, status: true, campaignId: true, pricePerPost: true },
  });
  if (!booking) {
    return { ok: false, error: "Booking not found" };
  }

  const allowed = COMPANY_BOOKING_TRANSITIONS[booking.status] ?? [];
  if (!allowed.includes(parsed.data.nextStatus)) {
    return {
      ok: false,
      error: `Cannot move a ${booking.status.toLowerCase().replace(/_/g, " ")} booking to ${parsed.data.nextStatus.toLowerCase().replace(/_/g, " ")}`,
    };
  }

  await applyBookingTransition(booking, parsed.data.nextStatus);

  revalidatePath(`${CAMPAIGNS_LIST_PATH}/${booking.campaignId}`);
  revalidatePath(CAMPAIGNS_LIST_PATH);
  revalidatePath(REPORTS_PATH);
  revalidatePath(OVERVIEW_PATH);
  return {
    ok: true,
    message: `Booking moved to ${parsed.data.nextStatus.toLowerCase().replace(/_/g, " ")}`,
  };
}

/**
 * Persist a validated booking transition and its side effects:
 *   - SCHEDULED stamps scheduledAt
 *   - LIVE stamps publishedAt
 *   - PAID upserts a PAID payout for the booking (idempotent, BP-IDEM-001)
 */
async function applyBookingTransition(
  booking: { id: string; pricePerPost: number },
  nextStatus: BookingStatus,
): Promise<void> {
  const now = new Date();
  const data: {
    status: BookingStatus;
    scheduledAt?: Date;
    publishedAt?: Date;
  } = { status: nextStatus };

  if (nextStatus === "SCHEDULED") data.scheduledAt = now;
  if (nextStatus === "LIVE") data.publishedAt = now;

  if (nextStatus === "PAID") {
    await prisma.$transaction([
      prisma.booking.update({ where: { id: booking.id }, data }),
      prisma.payout.upsert({
        where: { bookingId: booking.id },
        create: {
          bookingId: booking.id,
          amount: booking.pricePerPost,
          status: "PAID",
          paidAt: now,
        },
        update: { status: "PAID", paidAt: now, amount: booking.pricePerPost },
      }),
    ]);
    return;
  }

  await prisma.booking.update({ where: { id: booking.id }, data });
}

