// --- Local aggregation helpers ----------------------------------------------

function sumMetricRows(rows: { impressions: number; clicks: number; leads: number }[]) {
  return rows.reduce(
    (acc, row) => ({
      impressions: acc.impressions + row.impressions,
      clicks: acc.clicks + row.clicks,
      leads: acc.leads + row.leads,
    }),
    { impressions: 0, clicks: 0, leads: 0 },
  );
}

function aggregateBookingTotals(bookings: BookingWithRelations[]) {
  return bookings.reduce(
    (acc, booking) => {
      const perBooking = sumMetricRows(booking.metrics);
      return {
        impressions: acc.impressions + perBooking.impressions,
        clicks: acc.clicks + perBooking.clicks,
        leads: acc.leads + perBooking.leads,
      };
    },
    { impressions: 0, clicks: 0, leads: 0 },
  );
}

function aggregatePayouts(bookings: BookingWithRelations[]) {
  let paid = 0;
  let pending = 0;
  for (const booking of bookings) {
    if (!booking.payout) continue;
    if (booking.payout.status === "PAID") paid += booking.payout.amount;
    else pending += booking.payout.amount;
  }
  return { paid, pending };
}

// --- Brief display ----------------------------------------------------------

function BriefCard({
  brief,
}: {
  brief: {
    angle: string;
    hook: string;
    cta: string;
    audience: string;
    toneOfVoice: string;
    keyMessages: string[];
    doList: string[];
    dontList: string[];
    proofPoints: string[];
    generatedByAI: boolean;
  };
}) {
  return (
    <Card className="mt-6">
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle>Campaign brief</CardTitle>
          {brief.generatedByAI && <Badge variant="brand">AI-drafted</Badge>}
        </div>
      </CardHeader>
      <CardContent className="grid gap-5 md:grid-cols-2">
        <BriefText label="Angle" value={brief.angle} />
        <BriefText label="Hook" value={brief.hook} />
        <BriefText label="Call to action" value={brief.cta} />
        <BriefText label="Audience" value={brief.audience} />
        <BriefText label="Tone of voice" value={brief.toneOfVoice} />
        <BriefList label="Key messages" items={brief.keyMessages} />
        <BriefList label="Do" items={brief.doList} />
        <BriefList label="Don't" items={brief.dontList} />
        <BriefList label="Proof points" items={brief.proofPoints} />
      </CardContent>
    </Card>
  );
}

function BriefText({ label, value }: { label: string; value: string }) {
  if (!value) return null;
  return (
    <div>
      <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        {label}
      </p>
      <p className="mt-1 text-sm">{value}</p>
    </div>
  );
}

function BriefList({ label, items }: { label: string; items: string[] }) {
  if (items.length === 0) return null;
  return (
    <div>
      <p className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
        {label}
      </p>
      <ul className="mt-1 flex list-inside list-disc flex-col gap-1 text-sm">
        {items.map((item, index) => (
          <li key={index}>{item}</li>
        ))}
      </ul>
    </div>
  );
}

import Link from "next/link";
import { requireCompany } from "@/lib/auth-helpers";
import { prisma } from "@/lib/prisma";
import { PageHeader } from "@/components/app/dashboard-shell";
import { Card, CardContent } from "@/components/ui/card";
import { ButtonLink } from "@/components/ui/button";
import { ExportLeadsButton, type LeadRow } from "@/components/company/export-leads-button";
import { formatDate } from "@/lib/utils";
import { PAGE_SIZE_DEFAULT } from "@/lib/constants";

type SearchParams = Record<string, string | string[] | undefined>;

function firstValue(value: string | string[] | undefined): string {
  return Array.isArray(value) ? (value[0] ?? "") : (value ?? "");
}

export default async function LeadsPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>;
}) {
  const { company } = await requireCompany();
  const sp = await searchParams;
  const pageRaw = Number(firstValue(sp.page));
  const page = Number.isFinite(pageRaw) && pageRaw >= 1 ? Math.floor(pageRaw) : 1;

  // All leads are scoped through the booking → campaign → company chain (IDOR-safe).
  const where = { booking: { campaign: { companyProfileId: company.id } } };

  const [totalLeads, leads] = await Promise.all([
    prisma.lead.count({ where }),
    prisma.lead.findMany({
      where,
      orderBy: { capturedAt: "desc" },
      skip: (page - 1) * PAGE_SIZE_DEFAULT,
      take: PAGE_SIZE_DEFAULT,
      include: {
        booking: {
          include: {
            creator: { select: { displayName: true } },
            campaign: { select: { id: true, name: true } },
          },
        },
      },
    }),
  ]);

  const totalPages = Math.max(1, Math.ceil(totalLeads / PAGE_SIZE_DEFAULT));

  const exportRows: LeadRow[] = leads.map((lead) => ({
    name: lead.name,
    title: lead.title,
    company: lead.company,
    creatorName: lead.booking.creator.displayName,
    campaignName: lead.booking.campaign.name,
    capturedAt: lead.capturedAt.toISOString(),
  }));

  return (
    <>
      <PageHeader
        title="Leads"
        description={`${totalLeads} identifiable lead${totalLeads === 1 ? "" : "s"} across your campaigns.`}
        action={<ExportLeadsButton rows={exportRows} />}
      />

      {totalLeads === 0 ? (
        <Card className="p-12 text-center">
          <p className="text-sm text-muted-foreground">
            No leads captured yet. Leads appear here as your booked posts drive engagement.
          </p>
        </Card>
      ) : (
        <Card>
          <CardContent className="p-0">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-border text-left text-xs uppercase tracking-wide text-muted-foreground">
                    <th className="px-5 py-3 font-medium">Name</th>
                    <th className="px-5 py-3 font-medium">Title</th>
                    <th className="px-5 py-3 font-medium">Company</th>
                    <th className="px-5 py-3 font-medium">Source creator</th>
                    <th className="px-5 py-3 font-medium">Campaign</th>
                    <th className="px-5 py-3 font-medium">Captured</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {leads.map((lead) => (
                    <tr key={lead.id} className="transition-colors hover:bg-muted/40">
                      <td className="px-5 py-3 font-medium">{lead.name}</td>
                      <td className="px-5 py-3 text-muted-foreground">{lead.title}</td>
                      <td className="px-5 py-3 text-muted-foreground">{lead.company}</td>
                      <td className="px-5 py-3 text-muted-foreground">
                        {lead.booking.creator.displayName}
                      </td>
                      <td className="px-5 py-3">
                        <Link
                          href={`/app/campaigns/${lead.booking.campaign.id}`}
                          className="text-brand hover:text-brand-700"
                        >
                          {lead.booking.campaign.name}
                        </Link>
                      </td>
                      <td className="px-5 py-3 text-muted-foreground">
                        {formatDate(lead.capturedAt)}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      )}

      {totalPages > 1 && (
        <div className="mt-6 flex items-center justify-center gap-3">
          {page > 1 ? (
            <ButtonLink href={`/app/leads?page=${page - 1}`} variant="outline" size="sm">
              Previous
            </ButtonLink>
          ) : (
            <span className="text-sm text-muted-foreground opacity-50">Previous</span>
          )}
          <span className="text-sm text-muted-foreground">
            Page {page} of {totalPages}
          </span>
          {page < totalPages ? (
            <ButtonLink href={`/app/leads?page=${page + 1}`} variant="outline" size="sm">
              Next
            </ButtonLink>
          ) : (
            <span className="text-sm text-muted-foreground opacity-50">Next</span>
          )}
        </div>
      )}
    </>
  );
}

import Link from "next/link";
import { Eye, MousePointerClick, Target, Wallet, Megaphone } from "lucide-react";
import { requireCompany } from "@/lib/auth-helpers";
import { PageHeader } from "@/components/app/dashboard-shell";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { StatCard } from "@/components/ui/stat-card";
import { Badge } from "@/components/ui/badge";
import { MetricsAreaChart } from "@/components/company/metrics-area-chart";
import { formatCompact, formatEuros } from "@/lib/utils";
import {
  companyMetricSeries,
  campaignPerformanceRows,
  METRICS_WINDOW_DAYS,
} from "@/lib/company-queries";

const CAMPAIGN_STATUS_VARIANT: Record<string, "default" | "brand" | "success" | "outline"> = {
  DRAFT: "outline",
  ACTIVE: "brand",
  COMPLETED: "success",
  ARCHIVED: "default",
};

export default async function ReportsPage() {
  const { company } = await requireCompany();

  const [series, rows] = await Promise.all([
    companyMetricSeries(company.id),
    campaignPerformanceRows(company.id),
  ]);

  const totals = rows.reduce(
    (acc, row) => ({
      posts: acc.posts + row.postCount,
      impressions: acc.impressions + row.impressions,
      clicks: acc.clicks + row.clicks,
      leads: acc.leads + row.leads,
      spend: acc.spend + row.spend,
    }),
    { posts: 0, impressions: 0, clicks: 0, leads: 0, spend: 0 },
  );

  return (
    <>
      <PageHeader
        title="Reports"
        description="Aggregate performance across every campaign."
      />

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5">
        <StatCard label="Campaigns" value={rows.length} icon={<Megaphone className="size-5" />} />
        <StatCard
          label="Impressions"
          value={formatCompact(totals.impressions)}
          icon={<Eye className="size-5" />}
        />
        <StatCard
          label="Clicks"
          value={formatCompact(totals.clicks)}
          icon={<MousePointerClick className="size-5" />}
        />
        <StatCard
          label="Leads"
          value={formatCompact(totals.leads)}
          icon={<Target className="size-5" />}
        />
        <StatCard
          label="Committed spend"
          value={formatEuros(totals.spend)}
          icon={<Wallet className="size-5" />}
        />
      </div>

      <Card className="mt-6">
        <CardHeader>
          <CardTitle>Performance trend</CardTitle>
          <p className="text-sm text-muted-foreground">
            Clicks &amp; leads across all campaigns, last {METRICS_WINDOW_DAYS} days.
          </p>
        </CardHeader>
        <CardContent>
          <MetricsAreaChart data={series} series={["clicks", "leads"]} />
        </CardContent>
      </Card>

      <Card className="mt-6">
        <CardHeader>
          <CardTitle>By campaign</CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          {rows.length === 0 ? (
            <p className="p-6 text-sm text-muted-foreground">
              No campaigns yet. Create one to start seeing performance here.
            </p>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-border text-left text-xs uppercase tracking-wide text-muted-foreground">
                    <th className="px-5 py-3 font-medium">Campaign</th>
                    <th className="px-5 py-3 font-medium">Status</th>
                    <th className="px-5 py-3 font-medium">Posts</th>
                    <th className="px-5 py-3 font-medium">Impressions</th>
                    <th className="px-5 py-3 font-medium">Clicks</th>
                    <th className="px-5 py-3 font-medium">Leads</th>
                    <th className="px-5 py-3 font-medium">Spend</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border">
                  {rows.map((row) => (
                    <tr key={row.campaignId} className="transition-colors hover:bg-muted/40">
                      <td className="px-5 py-3">
                        <Link
                          href={`/app/campaigns/${row.campaignId}`}
                          className="font-medium hover:text-brand"
                        >
                          {row.name}
                        </Link>
                      </td>
                      <td className="px-5 py-3">
                        <Badge variant={CAMPAIGN_STATUS_VARIANT[row.status] ?? "default"}>
                          {row.status.toLowerCase()}
                        </Badge>
                      </td>
                      <td className="px-5 py-3 text-muted-foreground">{row.postCount}</td>
                      <td className="px-5 py-3 text-muted-foreground">
                        {formatCompact(row.impressions)}
                      </td>
                      <td className="px-5 py-3 text-muted-foreground">
                        {formatCompact(row.clicks)}
                      </td>
                      <td className="px-5 py-3 text-muted-foreground">
                        {formatCompact(row.leads)}
                      </td>
                      <td className="px-5 py-3 font-medium">{formatEuros(row.spend)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </CardContent>
      </Card>
    </>
  );
}

